def bipw(graph, w):
    # 二部グラフであるかどうか判定する
    # 二部グラフであるならば、同じ色を結ぶ最短パスの最小値がw以上か判定する

    # graph[v]:= [(nv, c)]
    n = len(graph) - 1

    # -1: 未訪問, 0or1: グループ分け
    visited = [-1 for i in range(n+1)]

    for i in range(1, n+1):
        if visited[i] != -1:
            continue

        visited[i] = 0
        que = [i]
        while que:
            nque = []
            while que:
                v = que.pop()
                for nv, c in graph[v]:
                    if c >= w:
                        break
                    if visited[nv] == visited[v]:
                        return False
                    if visited[nv] == -1:
                        visited[nv] = visited[v] ^ 1
                        nque.append(nv)
                    else:
                        continue
            que = nque

    return True

