def solve():
    h, w, m = next_array()
    count = [0] * (h * w + 1)
    count[0] = h * w
    ops = []
    for i in range(m):
        t, a, x = next_array()
        ops.append([t, a-1, x])

    r = h
    c = w
    row_visited = [False] * h
    col_visited = [False] * w
    for i in range(m - 1, -1, -1):
        t, a, x = ops[i]
        if t == 1:
            if not row_visited[a]:
                row_visited[a] = True
                count[0] -= c
                count[x] += c
                r -= 1
        else:
            if not col_visited[a]:
                col_visited[a] = True
                count[0] -= r
                count[x] += r
                c -= 1
    res = []
    for i in range(h * w):
        if count[i] > 0:
            res.append([str(i), str(count[i])])
    print(len(res))
    for p in res:
        print(" ".join(p))

