class UnionFind():
    def __init__(self, n):
        self.par = [-1] * n
        self.rank = [0] * n
        self.siz = [1] * n
    def find(self, x):
        if self.par[x] == -1: return x 
        else:
          self.par[x] = self.find(self.par[x]) 
          return self.par[x]
    def same(self, x, y):
        return self.find(x) == self.find(y)
    def union(self, x, y):
        rx = self.find(x)
        ry = self.find(y)
        if rx == ry: return False 
        if self.rank[rx] < self.rank[ry]: 
            rx, ry = ry, rx
        self.par[ry] = rx 
        if self.rank[rx] == self.rank[ry]:
            self.rank[rx] += 1
        self.siz[rx] += self.siz[ry]
        return True
    def size(self, x):
        return self.siz[self.find(x)]

