        for elem2 in basis:
            if elemcpy ^ elem2 < elemcpy:
                elemcpy = elemcpy ^ elem2
        if elemcpy != 0:
            basis.append(elemcpy)
            basis.sort(reverse=True)

    maxx = 0
    for elem in basis:
        if elem ^ maxx > maxx:
            maxx = elem ^ maxx

    return maxx

def main():
    n = int(input())
