    N = int(input().strip())
    S = []
    for _ in range(N):
        tmp = input().strip().split()
        del(tmp[0])
        S.append(tmp) 

    INF = 10**18
    # dp[i] : i番目の袋から出した後
    # dp[i][j] : j文字目まで完成しているときの最小スコア
    dp = [([0] + [INF]*(len(T))) for _ in range(N+1)]

    for i in range(1, N+1):
        # 何も取り出さないとき
        dp[i] = dp[i-1]

        for s in S[i-1]:
            # j:足す前の文字数
