                # 足した結果が正しいか
                if (T[0:j]+s == T[0:post_len]):
                    # 0から足したとき
                    if j == 0:
                        dp[i][post_len] = 1
                    else:
                        dp[i][post_len] = min(dp[i][post_len], dp[i-1][j] + 1)

    if dp[N][len(T)] > N:
        print(-1)
    else:
        print(dp[N][len(T)])

    return

