    for i in zip(*data):
        if nine != set(i):
            return False
    return True

def check_block(data):
    for i in range(0,9,3):
        for j in range(0,9,3):
            num = set()
            for row in range(3):
                for col in range(3):
                    num.add(data[row+i][col+j])
            if nine != num:
                return False
    return True

